INSERT INTO public.realtors (id, name, email, phone, specialization, bio, image_url, company_name, rating, languages, location, island, user_id, created_at, updated_at) VALUES ('22c5f61b-cc52-4e80-b6f0-c4e1c1662f87', 'Jolanda Strik', 'jolanda@harbourtownbonaire.com', '(+599) 717 5539', 'Makelaar / Eigenaar', 'Als makelaar help ik graag bij in het vinden van uw droomhuis of het verkopen van uw woning of appartement op Bonaire. Harbourtown Real Estate bestaat al sinds 1989 en sinds 2020 ben ik eigenaar van dit makelaarskantoor.', 'https://imhtjggudeidvmpgwjho.supabase.co/storage/v1/object/public/images/realtor-images/1751010729452-t2gjbc3g7z.webp', 'Harbourtown Real Estate', NULL, '{"Nederlands","English"}', 'Kralendijk', 'bonaire', 'b0ed5212-1c14-4186-aa01-2d98ac0a5fc3', '2025-06-27T07:52:10.259+00:00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.realtors (id, name, email, phone, specialization, bio, image_url, company_name, rating, languages, location, island, user_id, created_at, updated_at) VALUES ('729b3393-7392-4ab7-9fc7-04648746a52e', 'Bob Bartikoski', '?@remax.com', ' +5997177362', 'Luxury Properties', 'After working in large companies for most of my career, I got a point where I was ready to work for myself. After considering my options, I decided that selling real estate was a good option for me and after working for 5 years as a RE/MAX agent in Minnesota, I decided that I really enjoyed real estate, but that I was ready for a change of scenery. Soon after that, I was faced with a “life is too short” moment and decided that what I should do was to move to a Caribbean Island and sell real estate. In 2003 I moved to Bonaire and started the RE/MAX office on Bonaire, RE/MAX Paradise Homes, which has become one of the largest and most successful real estate brokers on Bonaire.', 'https://imhtjggudeidvmpgwjho.supabase.co/storage/v1/object/public/images/realtor-images/1751011126451-5jkagz6usll.jpg', 'Re/max Paradise Homes', NULL, '{"English"}', 'Kralendijk', 'bonaire', 'b0ed5212-1c14-4186-aa01-2d98ac0a5fc3', '2025-06-27T07:58:47.198+00:00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.realtors (id, name, email, phone, specialization, bio, image_url, company_name, rating, languages, location, island, user_id, created_at, updated_at) VALUES ('1e8c99fe-dd2f-4565-8d43-d8f7c2204cf0', 'Edwin Hekman', 'edwin.hekman@kwbonaire.com', '+599 701 3517', 'Broker/Owner', 'Edwin Hekman was born in Almelo and grew up in a small town in The Netherlands, called Den Ham. He married his wife, Manon, in 1999 and together they have 2 children: Ian and Tim.', 'https://imhtjggudeidvmpgwjho.supabase.co/storage/v1/object/public/images/realtor-images/1751011384720-igkz5tfb7x9.webp', 'Keller Williams Bonaire', NULL, '{"Nederlands","English"}', 'Kralendijk', 'bonaire', 'b0ed5212-1c14-4186-aa01-2d98ac0a5fc3', '2025-06-27T08:03:05.771+00:00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.realtors (id, name, email, phone, specialization, bio, image_url, company_name, rating, languages, location, island, user_id, created_at, updated_at) VALUES ('98bf3838-2474-423a-afff-beb3f2c4c8a9', 'Bonaire Realty', 'info@bonairerealty.com', '+599 717 1181', 'Sale, long term rentals ', 'Bonaire Realty is your real estate partner on Bonaire. We are straight forward real estate agents with extended local knowledge. Realistic, committed and determined. We are specialists in real estate and we know the importance of working with integrity and honesty. A direct and active approach provides the best results for you.', 'https://imhtjggudeidvmpgwjho.supabase.co/storage/v1/object/public/images/realtor-images/1751011740779-cv2dgcym8bq.png', 'Bonaire Realty', NULL, '{"Nederlands","English"}', 'Kralendijk', 'bonaire', 'b0ed5212-1c14-4186-aa01-2d98ac0a5fc3', '2025-06-27T08:09:02.098+00:00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.realtors (id, name, email, phone, specialization, bio, image_url, company_name, rating, languages, location, island, user_id, created_at, updated_at) VALUES ('eebae7cf-3662-4e0e-b66f-c2295aef997c', 'Jason Scholtz', 'jason@livinggoed.com', '+5999 511 9197', 'Makelaar', 'Makelaar Curacao? Livinggoed Real Estate Curacao is de makelaar op Curacao die u kan helpen met alle wensen wat betreft verhuur, verkoop, huur en koop op Curacao. Ook hebben wij een uniek concept als aankoopmakelaar op Curacao. ', 'https://imhtjggudeidvmpgwjho.supabase.co/storage/v1/object/public/images/realtor-images/1751012048006-50asebm8z26.webp', 'Living Goed Curacao', NULL, '{"Nederlands","English"}', 'Willemstad', 'curacao', 'b0ed5212-1c14-4186-aa01-2d98ac0a5fc3', '2025-06-27T08:14:09.04+00:00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.realtors (id, name, email, phone, specialization, bio, image_url, company_name, rating, languages, location, island, user_id, created_at, updated_at) VALUES ('6907e108-6ce3-40e4-b490-c46814d0296e', 'Jacqueline Remmelts', 'jacqueline@internationalfineliving.com', '+59995123803', 'Luxury Properties', 'Bij International Fine Living draait het om jou, je dromen en je toekomst. Of je nu je droomhuis wilt kopen of een woning wilt verkopen, wij staan klaar om je te helpen. We luisteren naar je wensen, combineren die met je budget en gebruiken al onze expertise en tools om jouw doelen te bereiken. Van een unieke villa aan het water tot een sfeervolle woning in de stad, wij zorgen dat jouw ervaring soepel en succesvol verloopt.', 'https://imhtjggudeidvmpgwjho.supabase.co/storage/v1/object/public/images/realtor-images/1751012295126-61s27o6bqs5.jpg', 'International Fine Living', NULL, '{"Nederlands","English"}', 'Willemstad', 'curacao', 'b0ed5212-1c14-4186-aa01-2d98ac0a5fc3', '2025-06-27T08:18:16.109+00:00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.realtors (id, name, email, phone, specialization, bio, image_url, company_name, rating, languages, location, island, user_id, created_at, updated_at) VALUES ('9defd7b4-87a1-48c3-b518-1d4ff9958bd4', 'Sanne Raatjes', 'info@ruseler.com', '+5999 516 2025', 'Luxury Properties', 'Ruseler Real Estate Curacao is the premier real estate agency located in the vibrant Jan Thiel Beach. With great passion and dedication, we work towards realizing dreams of real estate. Our mission is not just to sell properties. At Ruseler Real Estate Curacao, we always strive to exceed our clients’ expectations.
INSERT INTO public.realtors (id, name, email, phone, specialization, bio, image_url, company_name, rating, languages, location, island, user_id, created_at, updated_at) VALUES ('b9b161b6-e438-4c69-909e-1c88437a922f', 'Angela Heijboer', 'info@realestatecaribe.com', '+ 5999 736-1133', 'Sales and Rentals', 'Angela is a good-natured warm person, young and very driven. She has years of experience as a real estate agent in Curacao. She is very commercial and also responsible for our marketing department. She is very active and motivated to serve each client in the best possible way.', 'https://imhtjggudeidvmpgwjho.supabase.co/storage/v1/object/public/images/realtor-images/1751012837146-nlrkvm21d.png', 'Real Estate Caribe', NULL, '{"Nederlands","English"}', 'Willemstad', 'curacao', 'b0ed5212-1c14-4186-aa01-2d98ac0a5fc3', '2025-06-27T08:27:18.454+00:00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.realtors (id, name, email, phone, specialization, bio, image_url, company_name, rating, languages, location, island, user_id, created_at, updated_at) VALUES ('9eafd714-d8b3-4355-8cf3-92f914b4e726', 'Prima Casa Real Estate Group', 'prima@aruba-realty.com', '(+297) 5863350', 'Makelaar', 'At Prima Casa Real Estate Aruba, we don’t just sell properties—we help people find their place in paradise. With a strong reputation built on trust, professionalism, and local expertise, we are proud to be one of Aruba’s most dynamic and customer-focused real estate agencies. As our company continues to grow, we are looking for driven and personable individuals to join our team as Real Estate Sales Agents.', 'https://imhtjggudeidvmpgwjho.supabase.co/storage/v1/object/public/images/realtor-images/1751014062124-3mu0ehwfzf9.webp', 'Prima Casa Real Estate Group', NULL, '{"Nederlands","English"}', 'Oranjestad', 'aruba', 'b0ed5212-1c14-4186-aa01-2d98ac0a5fc3', '2025-06-27T08:47:43.028+00:00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.realtors (id, name, email, phone, specialization, bio, image_url, company_name, rating, languages, location, island, user_id, created_at, updated_at) VALUES ('1846d37b-d457-4dea-9c9f-14a43c2f0b2e', 'Real Estate Aruba', 'info@realestatearuba.com', '+297 593 8082', 'Sale, rental, property management', 'REAL ESTATE ARUBA . COM - Real Estate Aruba is a trusted and experienced real estate agency that has been serving clients in Aruba and worldwide for years. We are dedicated to providing professional and friendly service to fully satisfy our clients needs.
INSERT INTO public.realtors (id, name, email, phone, specialization, bio, image_url, company_name, rating, languages, location, island, user_id, created_at, updated_at) VALUES ('54a931e7-9a9f-4d9c-bfb3-656f0b22c8d3', 'Joase van der Biest', 'Joase@boldrealestatearuba.com', '(297) 564-1102', 'Makelaar', 'Bold Real Estate Aruba offers clients a tenacious spirit, worldly outlook, and solid experience, making them an important ally to buyers and sellers on the island of Aruba.', 'https://imhtjggudeidvmpgwjho.supabase.co/storage/v1/object/public/images/realtor-images/1751014690345-q7chm1jn8ja.png', 'Bold Real Estate Aruba', NULL, '{"Nederlands","English"}', 'Oranjestad', 'aruba', 'b0ed5212-1c14-4186-aa01-2d98ac0a5fc3', '2025-06-27T08:58:11.59+00:00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.realtors (id, name, email, phone, specialization, bio, image_url, company_name, rating, languages, location, island, user_id, created_at, updated_at) VALUES ('0aa6c036-dbfe-4b59-9f00-2a26e235d325', 'Jan Falcone', 'info@arubapalmsrealtors.com', '+297 593-8700', 'Owner / broker', 'Aruba Palms Realtors has been featured on House Hunters International as a leader in Real Estate Aruba and Aruba Rentals. We pride ourselves in providing excellent customer satisfaction in selling, purchasing, or renting realty in Aruba.', 'https://imhtjggudeidvmpgwjho.supabase.co/storage/v1/object/public/images/realtor-images/1751014928583-f551gbf8ekb.webp', 'Aruba Palms Realtors', NULL, '{"English"}', 'Noord', 'aruba', 'b0ed5212-1c14-4186-aa01-2d98ac0a5fc3', '2025-06-27T09:02:09.494+00:00', NULL) ON CONFLICT DO NOTHING;
